    [, $session]=agentApi('/session');$csrf=$session['csrf'];
    [$status]=agentApi('/login',['email'=>$email,'password'=>$password]);agentCheck($status===200,'owner signs in for pairing');
    [$status,$info]=agentApi('/automation/pair/'.$pair['id']);agentCheck($status===200&&$info['device_name']==='Test PC','owner sees the device being paired');
    [$status]=agentApi('/automation/pair/'.$pair['id'].'/approve',[]);agentCheck($status===200,'owner approves narrow poller access');
    [$status,$finished]=agentApi('/automation/pair/finish',['id'=>$pair['id'],'verifier'=>$verifier]);$token=$finished['token']??'';
    agentCheck($status===200&&strlen($token)===43,'paired computer receives its credential');
    [$status,$empty]=agentApi('/automation/ready',null,$token);agentCheck($status===200&&$empty['ready']===false,'empty queue costs no model call');
    $taskKey=bin2hex(random_bytes(16));$instruction='Research the public website and update this lead with sources.';
    [$status,$requested]=agentApi('/leads/'.$lead.'/agent-requests',['instruction'=>$instruction,'request_key'=>$taskKey]);
    agentCheck($status===200&&($requested['queued']??false)===true,'signed-in user queues a free-form lead task');
    [$status,$replayed]=agentApi('/leads/'.$lead.'/agent-requests',['instruction'=>$instruction,'request_key'=>$taskKey]);
    agentCheck($status===200&&($replayed['replayed']??false)===true&&$replayed['id']===$requested['id'],'request retry does not duplicate work');
    [$status]=agentApi('/leads/'.$lead.'/agent-requests',['instruction'=>'Different action','request_key'=>$taskKey]);
    agentCheck($status===409,'request key cannot be reused for different instructions');
    $queuedRequest=query('SELECT w.kind,w.source_activity_id,a.body FROM agent_work_items w JOIN activities a ON a.id=w.source_activity_id WHERE w.id=?',[$requested['id']])->fetch();
    $requestBody=json_decode($queuedRequest['body'],true);
    agentCheck($queuedRequest['kind']==='user_request'&&$requestBody['instruction']===$instruction&&$requestBody['requested_by_user_id']===$user,'request is explicitly typed and attributed');
    $_SESSION=['workspace_id'=>$workspace,'user_id'=>$user,'user_name'=>'Test Owner','user_role'=>'owner'];
    try{hostedWrite('update_lead_website',['id'=>$lead,'version'=>1,'value'=>'https://example.org','provenance'=>'Public test source','evidence_type'=>'public_source']);agentCheck(false,'public source without URL should fail');}catch(RuntimeException $e){agentCheck($e->getCode()===422,'public-source edit requires URL');}
    $profileEdit=hostedWrite('update_lead_website',['id'=>$lead,'version'=>1,'value'=>'https://example.org','provenance'=>'Synthetic official site for test','source_activity_id'=>$queuedRequest['source_activity_id'],'evidence_type'=>'public_source','source_url'=>'https://example.org/about']);
    $profileAudit=query("SELECT body FROM activities WHERE workspace_id=? AND lead_id=? AND kind='profile_updated' ORDER BY created_at DESC,id DESC LIMIT 1",[$workspace,$lead])->fetchColumn();
    agentCheck(($profileEdit['changed']??false)===true&&json_decode($profileAudit,true)['source_url']==='https://example.org/about','public research edit retains provenance and source');
    $completed=hostedWrite('resolve_agent_work',['id'=>$requested['id'],'decision'=>'done','reason'=>'Updated website from the cited public test source.','sources'=>['https://example.org/about']]);
    agentCheck(($completed['sources'][0]??'')==='https://example.org/about'&&($completed['actions'][0]['field']??'')==='website','free-form task report retains actual profile edit and research source');
    $activity=uid();$work=uid();
    query('INSERT INTO activities (id,workspace_id,lead_id,kind,body,actor) VALUES (?,?,?,?,?,?)',[$activity,$workspace,$lead,'note','{"text":"Lead was unavailable"}','Test Owner']);
    query('INSERT INTO agent_work_items (id,workspace_id,lead_id,source_activity_id,kind) VALUES (?,?,?,?,?)',[$work,$workspace,$lead,$activity,'busy_call']);
    [$status,$ready]=agentApi('/automation/ready',null,$token);agentCheck($status===200&&$ready['ready']===true,'new work is visible to deterministic poller');
    $_SESSION=['workspace_id'=>$workspace,'user_id'=>$user,'user_name'=>'Test Owner','user_role'=>'owner'];
    $scheduled=hostedWrite('schedule_agent_followup',['id'=>$work,'title'=>'Call again','due_at'=>gmdate('Y-m-d\TH:i:s',time()+86400).'.000Z','summary'=>'Created a follow-up after the busy note.']);
    [$status,$reports]=agentApi('/agent-reports');$scheduledReport=array_values(array_filter($reports,fn($row)=>$row['id']===$work))[0]??[];
    agentCheck($status===200&&($scheduledReport['result']['actions'][0]['task_id']??'')===$scheduled['task_id'],'user report records the exact action');
    [$status,$reversal]=agentApi('/agent-work/'.$work.'/request-reversal',['reason'=>'No longer needed']);
    agentCheck($status===200&&isset($reversal['work_id']),'user request queues separate reversal work');
    $undone=hostedWrite('reverse_agent_work',['id'=>$reversal['work_id']]);
    agentCheck(($undone['status']??'')==='done'&&query('SELECT status FROM tasks WHERE id=?',[$scheduled['task_id']])->fetchColumn()==='cancelled','agent reverses an unchanged pending follow-up');
    $activity2=uid();$work2=uid();
    query('INSERT INTO activities (id,workspace_id,lead_id,kind,body,actor) VALUES (?,?,?,?,?,?)',[$activity2,$workspace,$lead,'note','{"text":"Another missed call"}','Test Owner']);
    query('INSERT INTO agent_work_items (id,workspace_id,lead_id,source_activity_id,kind) VALUES (?,?,?,?,?)',[$work2,$workspace,$lead,$activity2,'busy_call']);
    $scheduled2=hostedWrite('schedule_agent_followup',['id'=>$work2,'title'=>'Second call','due_at'=>gmdate('Y-m-d\TH:i:s',time()+172800).'.000Z','summary'=>'Made a second internal follow-up.']);
    query('UPDATE tasks SET due_at=DATE_ADD(due_at,INTERVAL 1 HOUR) WHERE id=?',[$scheduled2['task_id']]);
    [$status,$reversal2]=agentApi('/agent-work/'.$work2.'/request-reversal',['reason'=>'Check this changed follow-up']);
    $changed=hostedWrite('reverse_agent_work',['id'=>$reversal2['work_id']]);
    agentCheck(($changed['status']??'')==='needs_review'&&query('SELECT status FROM tasks WHERE id=?',[$scheduled2['task_id']])->fetchColumn()==='pending','changed follow-up is left for human review');
    [$status,$empty]=agentApi('/automation/ready',null,$token);agentCheck($status===200&&$empty['ready']===false,'resolved queue returns to empty');
    [$status,$reports]=agentApi('/agent-reports');
    $reviewRow=array_values(array_filter($reports,fn($r)=>$r['id']===$reversal2['work_id']))[0]??[];
    agentCheck($status===200&&isset($reviewRow['review_token'],$reviewRow['source_note'],$reviewRow['original_result']),'reversal review includes context and concurrency token');
    $review=['action'=>'close','reason'=>'Keep the changed follow-up.','review_token'=>$reviewRow['review_token'],'request_id'=>bin2hex(random_bytes(16))];
    $savedCsrf=$csrf;$csrf='invalid';
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',$review);agentCheck($status===403,'review requires CSRF');$csrf=$savedCsrf;
    [$status]=agentApi('/agent-work/'.uid().'/review',$review);agentCheck($status===404,'unknown work is inaccessible');
    query('INSERT INTO workspaces (id,name) VALUES (?,?)',[$otherWorkspace,'Review isolation test']);
    $otherEmail='other-'.$email;
    query('INSERT INTO users (id,workspace_id,name,email,password_hash,role) VALUES (?,?,?,?,?,?)',[uid(),$otherWorkspace,'Other Owner',$otherEmail,password_hash($password,PASSWORD_DEFAULT),'owner']);
    [$status]=agentApi('/login',['email'=>$otherEmail,'password'=>$password]);agentCheck($status===200,'other workspace owner signs in');
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',$review);agentCheck($status===404,'known work in another workspace is inaccessible');
    [$status]=agentApi('/login',['email'=>$email,'password'=>$password]);agentCheck($status===200,'original owner signs back in');
    query("UPDATE users SET role='collector' WHERE id=?",[$user]);
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',$review);agentCheck($status===403,'collector cannot review');
    query("UPDATE users SET role='salesperson' WHERE id=?",[$user]);query('UPDATE leads SET owner_user_id=NULL WHERE id=?',[$lead]);
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',$review);agentCheck($status===404,'unassigned salesperson cannot review');
    query('UPDATE leads SET owner_user_id=? WHERE id=?',[$user,$lead]);
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',$review+['unexpected'=>'no']);agentCheck($status===422,'extra fields rejected');
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',array_replace($review,['review_token'=>str_repeat('0',64)]));agentCheck($status===409,'stale report rejected');
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',array_replace($review,['reason'=>' ']));agentCheck($status===422,'review reason required');
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',$review);agentCheck($status===200,'assigned salesperson closes reversal review');
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',$review);agentCheck($status===200,'exact retry is idempotent');
    [$status]=agentApi('/agent-work/'.$reversal2['work_id'].'/review',array_replace($review,['request_id'=>bin2hex(random_bytes(16))]));agentCheck($status===409,'competing review cannot overwrite decision');
    $closed=json_decode(query('SELECT result FROM agent_work_items WHERE id=?',[$reversal2['work_id']])->fetchColumn(),true);
    agentCheck($closed['summary']===$changed['summary']&&$closed['human_review']['actor']==='Test Owner','agent report and reviewer retained');
    agentCheck(query('SELECT status FROM tasks WHERE id=?',[$scheduled2['task_id']])->fetchColumn()==='pending','review does not close follow-up task');
    agentCheck((int)query("SELECT COUNT(*) FROM activities WHERE workspace_id=? AND kind='agent_work_reviewed'",[$workspace])->fetchColumn()===1,'retry creates one durable audit');
    [$status,$empty]=agentApi('/automation/ready',null,$token);agentCheck($status===200&&$empty['ready']===false,'closed review is not polled again');
    $activity3=uid();$work3=uid();
    query('INSERT INTO activities (id,workspace_id,lead_id,kind,body,actor) VALUES (?,?,?,?,?,?)',[$activity3,$workspace,$lead,'note','{"text":"Uncertain callback"}','Test Owner']);
    $report=json_encode(['summary'=>'Clarify callback time.','actions'=>[]]);
    query("INSERT INTO agent_work_items (id,workspace_id,lead_id,source_activity_id,kind,status,result) VALUES (?,?,?,?,?,'needs_review',?)",[$work3,$workspace,$lead,$activity3,'review_note',$report]);
    $correction=['action'=>'request_correction','reason'=>'Check current schedule for tomorrow at 10am Africa/Nairobi.','review_token'=>hash('sha256',$report),'request_id'=>bin2hex(random_bytes(16))];
    [$status,$queued]=agentApi('/agent-work/'.$work3.'/review',$correction);agentCheck($status===200&&!empty($queued['next_work_id']),'correction queues separate work');
    [$status,$again]=agentApi('/agent-work/'.$work3.'/review',$correction);agentCheck($status===200&&$again['next_work_id']===$queued['next_work_id'],'correction retry does not duplicate work');
    [$status,$ready]=agentApi('/automation/ready',null,$token);agentCheck($status===200&&$ready['ready']===true,'explicit new work wakes poller');
    $next=query('SELECT w.*,a.body FROM agent_work_items w JOIN activities a ON a.id=w.source_activity_id WHERE w.id=?',[$queued['next_work_id']])->fetch();
    $context=json_decode($next['body'],true);agentCheck($next['status']==='pending'&&$next['kind']==='user_request'&&$context['instruction']===$correction['reason']&&$context['reviewed_work_id']===$work3&&$context['agent_report']['summary']==='Clarify callback time.','correction becomes explicit user work and retains context');
    $_SESSION=['workspace_id'=>$workspace,'user_id'=>$user,'user_name'=>'Test Owner','user_role'=>'salesperson'];
    try{hostedWrite('resolve_agent_work',['id'=>$work3,'decision'=>'done','reason'=>'Repeat']);agentCheck(false,'closed item cannot be reprocessed');}catch(RuntimeException $e){agentCheck($e->getCode()===409,'MCP refuses closed item');}
    query("UPDATE users SET role='owner' WHERE id=?",[$user]);
    [$status]=agentApi('/automation/revoke-self',[],$token);agentCheck($status===200,'local uninstall can revoke polling credential');
    [$status]=agentApi('/automation/ready',null,$token);agentCheck($status===401,'revoked poller cannot check the queue');
}finally{
    query('DELETE FROM agent_poll_tokens WHERE workspace_id=?',[$workspace]);
    query('DELETE FROM agent_poll_pairings WHERE workspace_id=?',[$workspace]);
